package mrpapermoon.whisper.contacts.dbimport androidx.room.TypeConverterimport mrpapermoon.whisper.entity.WhispererColorimport mrpapermoon.whisper.entity.WhispererIcon@Suppress("unused")class RoomTypeConverters {	@TypeConverter	fun serialize(icon: WhispererIcon): Int = icon.ordinal	@TypeConverter	fun deserializeUserIcon(value: Int): WhispererIcon = WhispererIcon.entries[value]	@TypeConverter	fun serialize(color: WhispererColor): Int = color.ordinal	@TypeConverter	fun deserializeUserColor(value: Int): WhispererColor = WhispererColor.entries[value]}